semaphore empty = N;
semaphore full  = 0;
semaphore mutex = 1;

producer(x) {
    P(empty);
    P(mutex);
    put(x);
    V(mutex);
    V(full);
}

consumer() {
    P(full);
    P(mutex);
    x = get();
    V(mutex);
    V(empty);
    return x;
}

int count = 0;
mutex m;
condition cv;

barrier_wait() {
    lock(m);
    count++;
    if (count == 4) {
        broadcast(cv);
    } else {
        while (count < 4) {
            wait(cv, m);
        }
    }
    unlock(m);
}
